<script setup lang="ts">
import {onMounted,onUnmounted,reactive,ref} from 'vue';
import {ElMessage,ElMessageBox} from 'element-plus';
import {api,errorText} from '../../api/zenflow/client';
interface Model{id:string;name:string;modelName:string;provider:string;baseUrl:string;dimensions:number;version:number;tested:boolean;published:boolean;active:boolean;hasApiKey:boolean}
const rows=ref<Model[]>([]),busy=ref(''),loading=ref(false),open=ref(false),editing=ref('');
const form=reactive({name:'',modelName:'',provider:'OpenAI-compatible',baseUrl:'',apiKey:'',dimensions:1536,expectedVersion:0});
let original='',disposed=false,generation=0;
async function load(){const current=++generation;loading.value=true;try{const result=await api.get('/embedding-models');if(!disposed&&current===generation)rows.value=result.data;}catch(error){if(!disposed&&current===generation)ElMessage.error(errorText(error));}finally{if(!disposed&&current===generation)loading.value=false;}}
function edit(row?:Model){editing.value=row?.id||'';Object.assign(form,{name:row?.name||'',modelName:row?.modelName||'',provider:row?.provider||'OpenAI-compatible',baseUrl:row?.baseUrl||'',apiKey:'',dimensions:row?.dimensions||1536,expectedVersion:row?.version||0});original=JSON.stringify(form);open.value=true;}
async function close(done:()=>void){if(busy.value)return;if(JSON.stringify(form)!==original){try{await ElMessageBox.confirm('嵌入模型配置尚未保存，是否放弃修改？','放弃修改',{confirmButtonText:'放弃',cancelButtonText:'继续编辑'});}catch{return;}}done();}
async function save(){busy.value='save';try{if(editing.value)await api.put('/embedding-models/'+editing.value,form);else await api.post('/embedding-models',form);form.apiKey='';if(!disposed){open.value=false;ElMessage.success('已保存，请测试连接后激活');await load();}}catch(error){if(!disposed)ElMessage.error(errorText(error));}finally{if(!disposed)busy.value='';}}
async function test(row:Model){busy.value=row.id;try{await api.post('/embedding-models/'+row.id+'/test',{expectedVersion:row.version});if(!disposed){ElMessage.success('嵌入模型连接与向量维度检查通过');await load();}}catch(error){if(!disposed)ElMessage.error(errorText(error));}finally{if(!disposed)busy.value='';}}
async function activate(row:Model){busy.value=row.id;try{await api.post('/embedding-models/'+row.id+'/activate',{expectedVersion:row.version});if(!disposed){ElMessage.success('嵌入模型已激活，后续资料准备将使用此配置');await load();}}catch(error){if(!disposed)ElMessage.error(errorText(error));}finally{if(!disposed)busy.value='';}}
onMounted(load);onUnmounted(()=>{disposed=true;generation++;form.apiKey='';});
</script>
<template><section><div class="page-heading"><div><h2>参考资料的嵌入模型</h2><p class="muted">用于把参考资料转换成可检索的向量。独立于聊天模型配置。</p></div><el-button type="primary" :disabled="!!busy" @click="edit()">添加嵌入模型</el-button></div><el-alert title="使用 OpenAI 兼容 Embeddings 接口。发布后的配置固定保留；更换供应商或密钥，请创建新配置。" type="info" :closable="false"/>
<div v-loading="loading" class="models"><el-empty v-if="!rows.length" description="尚未配置嵌入模型。"/><article v-for="row in rows" :key="row.id" class="model-card"><div class="card-heading"><h2>{{row.name}}</h2><el-tag :type="row.active?'success':'info'">{{row.active?'当前配置':row.tested?'已测试':'待测试'}}</el-tag></div><p>{{row.modelName}} · {{row.dimensions}} 维</p><p class="endpoint">{{row.baseUrl}}</p><p class="muted">密钥{{row.hasApiKey?'已设置':'未设置'}} · 版本 {{row.version}}</p><div class="actions"><el-button :disabled="row.published||!!busy" @click="edit(row)">编辑</el-button><el-button :disabled="!!busy" :loading="busy===row.id" @click="test(row)">测试连接</el-button><el-button type="primary" :disabled="row.active||!row.tested||!!busy" @click="activate(row)">激活</el-button></div></article></div>
<el-dialog v-model="open" :title="editing?'编辑嵌入模型':'添加嵌入模型'" width="min(580px,94vw)" :close-on-click-modal="false" :before-close="close" @closed="form.apiKey=''"><el-form label-position="top"><el-form-item label="显示名称"><el-input v-model="form.name" maxlength="64"/></el-form-item><el-form-item label="模型标识"><el-input v-model="form.modelName" maxlength="100"/></el-form-item><el-form-item label="供应商标签"><el-input v-model="form.provider" maxlength="100"/></el-form-item><el-form-item label="API 基础地址"><el-input v-model="form.baseUrl" maxlength="100" placeholder="https://供应商地址/v1"/></el-form-item><el-form-item label="API 密钥"><el-input v-model="form.apiKey" type="password" autocomplete="new-password" show-password :placeholder="editing?'留空保留已有密钥':'只保存在服务端'"/></el-form-item><el-form-item label="向量维度"><el-input-number v-model="form.dimensions" :min="1" :max="4096"/><span class="muted">填写供应商支持的维度，连通测试会核对实际结果。</span></el-form-item></el-form><template #footer><el-button :disabled="!!busy" @click="close(()=>open=false)">取消</el-button><el-button type="primary" :loading="busy==='save'" @click="save">保存</el-button></template></el-dialog>
</section></template>
